  if (!status.piper) {
    size += 21
  }

  // FFmpeg ~101MB
  if (!status.ffmpeg) {
    size += 101
  }

  // Voices are now installed on-demand, not included in initial setup
  const includeSilero = false

  return { size, includeSilero }
